using System.Net;
using System.Net.Sockets;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>A real HTTP server on a loopback port that plays the provider and records what it receives.</summary>
public sealed class FakeProviderServer : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Task loop;

    public FakeProviderServer(HttpStatusCode status, string body, string contentType = "application/json")
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"http://127.0.0.1:{port}/");
        listener.Start();

        loop = Task.Run(async () =>
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                Method = context.Request.HttpMethod;
                Path = context.Request.Url!.AbsolutePath;
                ContentType = context.Request.ContentType;
                Body = await reader.ReadToEndAsync();

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = (int)status;
                context.Response.ContentType = contentType;
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        });
    }

    public Uri BaseAddress { get; }
    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? ContentType { get; private set; }
    public string? Body { get; private set; }

    public void Dispose()
    {
        listener.Close();
        loop.Wait(TimeSpan.FromSeconds(5));
    }
}
