using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static Task<AuthorizationOutcome> Authorize(FakeProviderServer server, Money? amount = null)
    {
        var client = new HttpClient { BaseAddress = server.BaseAddress };
        return new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", amount ?? new Money(12.50m, "eur"), CancellationToken.None);
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        using var server = new FakeProviderServer(HttpStatusCode.OK, """{"status":"approved"}""");

        await Authorize(server);

        Assert.Equal("POST", server.Method);
        Assert.Equal("/v1/authorizations", server.Path);
        Assert.StartsWith("application/json", server.ContentType);
        using var sent = JsonDocument.Parse(server.Body!);
        var root = sent.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        using var server = new FakeProviderServer(HttpStatusCode.OK, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(server));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        using var server = new FakeProviderServer(HttpStatusCode.OK, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(server));
    }

    [Fact]
    public async Task Unknown_fields_in_the_answer_are_ignored()
    {
        using var server = new FakeProviderServer(HttpStatusCode.OK, """{"id":"x1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(server));
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_unrelated_body()
    {
        using var server = new FakeProviderServer(HttpStatusCode.PaymentRequired, """{"error":"insufficient_funds"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(server));
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_empty_body()
    {
        using var server = new FakeProviderServer(HttpStatusCode.PaymentRequired, "");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(server));
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_failure_statuses_surface_as_errors_instead_of_a_decline(HttpStatusCode status)
    {
        using var server = new FakeProviderServer(status, """{"status":"declined"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(server));
    }

    [Fact]
    public async Task A_body_that_is_not_json_surfaces_as_an_error()
    {
        using var server = new FakeProviderServer(HttpStatusCode.OK, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<Exception>(() => Authorize(server));
    }

    [Theory]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_treated_as_approved(string body)
    {
        using var server = new FakeProviderServer(HttpStatusCode.OK, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(server));
    }
}
